  /* ---------- scroll lock ---------- */
  function syncScrollLock() {
    var open = modal.classList.contains('is-open');
    document.documentElement.classList.toggle('no-scroll', open);
    document.body.classList.toggle('no-scroll', open);
  }

  /* ---------- render ---------- */
  function render() {
    tabs.forEach(function (t) {
      var on = Number(t.dataset.stepBtn) === step;
      t.classList.toggle('is-active', on);
      t.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    panes.forEach(function (p) { p.classList.toggle('is-active', Number(p.dataset.stepPane) === step); });
    btnPrev.disabled = step === 0;
    btnNext.hidden = step === STEP_COUNT - 1;
    btnFinish.hidden = step !== STEP_COUNT - 1;
    progressEl.style.width = ((step + 1) / STEP_COUNT) * 100 + '%';
    qs('#rootwizard', modal).setAttribute('data-step', String(step));
  }

  function centerActiveTab() {
    if (!wizardTabs || !wizardTabs.scrollWidth) return;
    var active = tabs.filter(function (t) { return Number(t.dataset.stepBtn) === step; })[0];
    if (!active) return;
    var cRect = wizardTabs.getBoundingClientRect();
    var tRect = active.getBoundingClientRect();
    var target = wizardTabs.scrollLeft + (tRect.left - cRect.left) + tRect.width / 2 - cRect.width / 2;
    var max = Math.max(0, wizardTabs.scrollWidth - wizardTabs.clientWidth);
    var left = Math.min(Math.max(0, target), max);
    if (Math.abs(wizardTabs.scrollLeft - left) < 2) return;
    if (wizardTabs.scrollTo) wizardTabs.scrollTo({ left: left, behavior: 'smooth' });
    else wizardTabs.scrollLeft = left;
  }

  function setStep(n) {
    var next = Math.max(0, Math.min(STEP_COUNT - 1, n));
    if (next === step) return;
    step = next;
    render();
    if (wizardBody) wizardBody.scrollTo ? wizardBody.scrollTo({ top: 0, behavior: 'smooth' }) : (wizardBody.scrollTop = 0);
    centerActiveTab();
  }
