    var rect = wizardBody.getBoundingClientRect();
    var y = lastY;
    if (typeof y === 'number') {
      var delta = 0;
      if (y < rect.top + 56) delta = -Math.min(18, (rect.top + 56 - y) / 4);
      else if (y > rect.bottom - 56) delta = Math.min(18, (y - (rect.bottom - 56)) / 4);
      if (delta) {
        var before = wizardBody.scrollTop;
        wizardBody.scrollTop += delta;
        if (wizardBody.scrollTop !== before) {
          if (ptr && ptr.started) place(ptr.li, ptr.ul, y);
          else if (ndrag) place(ndrag.li, ndrag.ul, y);
        }
      }
    }
    rafId = requestAnimationFrame(tick);
  }
  function ensureTick() { if (!rafId) rafId = requestAnimationFrame(tick); }
