function scrollByOptions(node, opts, fallbackLeft, fallbackTop) {
  if (typeof node.scrollTo === "function") {
    try {
      node.scrollTo(opts);
      if (typeof fallbackTop === "number" && node.scrollTop !== fallbackTop && !opts.behavior) node.scrollTop = fallbackTop;
      if (typeof fallbackLeft === "number" && Math.abs(node.scrollLeft - fallbackLeft) > 1 && !opts.behavior) node.scrollLeft = fallbackLeft;
      return;
    } catch (err) { /* старые браузеры: обычные числовые значения */ }
  }
  if (typeof fallbackTop === "number") node.scrollTop = fallbackTop;
  if (typeof fallbackLeft === "number") node.scrollLeft = fallbackLeft;
}

